const regions = [
 {id:'florida-keys',name:'Florida Keys',line:'Sea glass, sunshine, and a little color',options:[{id:'signature',name:'The Keys collection',exterior:'Sea-glass aqua stucco, crisp white trim, and a coral door.',interior:'Aqua cabinetry, light oak, white linen, and soft coral accents.'}]},
 {id:'coastal-california',name:'Coastal California',line:'Quiet colors. Natural textures.',options:[{id:'signature',name:'The California collection',exterior:'Cream stucco, driftwood tones, and a sage-green door.',interior:'Pale oak, sage linen, and a warm neutral palette.'}]},
 {id:'rural-america',name:'Rural America',line:'Familiar warmth, simply expressed',options:[{id:'signature',name:'The Rural collection',exterior:'Barn-red stucco, ivory trim, and charcoal accents.',interior:'Barn-red lower cabinets, ivory uppers, warm oak, and woven textiles.'}]},
 {id:'colorado-mountains',name:'Colorado Mountains',line:'Deep greens. Warm wood. A restful retreat.',options:[{id:'signature',name:'The Colorado collection',exterior:'Forest-green stucco, cedar tones, and graphite detailing.',interior:'Forest-green cabinetry, a warm wood divider, and charcoal wool tones.'}]},
 {id:'new-mexico-plains',name:'New Mexico Plains',line:'Earth, sky, and the colors between',options:[{id:'signature',name:'The New Mexico collection',exterior:'Adobe-clay stucco, turquoise door, and bronze details.',interior:'Clay accents, sandy tones, natural oak, and a turquoise bathroom door.'}]}
];
let selectedRegion=regions[0];let selectedOption=selectedRegion.options[0];
const tabs=document.querySelector('.region-tabs');const variant=document.querySelector('#variant');
function updateView(){document.querySelector('#region-description').textContent=selectedRegion.line;document.querySelector('#style-title').textContent=selectedOption.name;for(const type of ['exterior','interior']){const img=document.querySelector('#'+type+'-image');img.src='/assets/'+selectedRegion.id+'-'+selectedOption.id+'-'+type+'.webp';img.alt=selectedRegion.name+' — '+selectedOption.name+' '+(type==='interior'?'interior at twilight':'exterior');document.querySelector('#'+type+'-note').textContent=selectedOption[type]}document.querySelector('#style-panel').setAttribute('aria-labelledby','tab-'+selectedRegion.id);updateContact()}
function selectRegion(region){selectedRegion=region;selectedOption=region.options[0];tabs.querySelectorAll('button').forEach(b=>{const active=b.dataset.region===region.id;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});variant.innerHTML='';region.options.forEach(o=>{const el=document.createElement('option');el.value=o.id;el.textContent=o.name;variant.append(el)});updateView()}
regions.forEach((r,i)=>{const b=document.createElement('button');b.id='tab-'+r.id;b.dataset.region=r.id;b.setAttribute('role','tab');b.setAttribute('aria-controls','style-panel');b.textContent=r.name;b.onclick=()=>selectRegion(r);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?regions.length-1:(i+(e.key==='ArrowRight'?1:-1)+regions.length)%regions.length;selectRegion(regions[n]);tabs.children[n].focus()}};tabs.append(b)});
variant.onchange=()=>{selectedOption=selectedRegion.options.find(o=>o.id===variant.value);updateView()};
const lightbox=document.querySelector('#lightbox');document.querySelectorAll('.image-button').forEach(b=>b.onclick=()=>{const source=document.querySelector('#'+b.dataset.view+'-image');lightbox.querySelector('img').src=source.src;lightbox.querySelector('img').alt=source.alt;lightbox.querySelector('p').textContent=source.alt;lightbox.showModal()});document.querySelector('.close-dialog').onclick=()=>lightbox.close();lightbox.onclick=e=>{if(e.target===lightbox)lightbox.close()};
const SALES_EMAIL='';
function updateContact(){if(!SALES_EMAIL)return;const a=document.querySelector('#email-cta');const body=`Hello Sundello,\n\nI am interested in the Origin 320.\nRoof preference: ${window.originRoofSelection?.roofLabel || "Not selected"} / ${window.originRoofSelection?.finishLabel || ""}\nRegional palette: ${selectedRegion.name} / ${selectedOption.name}\nProject location: \nDesired timeline: \n\nPlease send information about pricing, available finishes, and next steps.\n\nName: \nPhone (optional): `;a.href='mailto:'+SALES_EMAIL+'?subject='+encodeURIComponent('Origin 320 project inquiry')+'&body='+encodeURIComponent(body);a.removeAttribute('download');a.innerHTML='Email Sundello <span aria-hidden="true">↗</span>';document.querySelector('#contact-helper').textContent='Opens your email app with your selected style included.'}
selectRegion(regions[0]);

const reveal=document.querySelector('#finish-reveal');
function setReveal(value){const amount=Math.max(0,Math.min(100,Number(value)));reveal.value=amount;reveal.closest('.compare-frame').style.setProperty('--reveal',amount+'%');reveal.setAttribute('aria-valuetext',amount+' percent white and stainless, '+(100-amount)+' percent desert adobe')}
reveal.addEventListener('input',()=>setReveal(reveal.value));
document.querySelectorAll('[data-reveal]').forEach(button=>button.addEventListener('click',()=>setReveal(button.dataset.reveal)));
let revealDragging=false;
function revealAt(event){const r=reveal.getBoundingClientRect();setReveal((event.clientX-r.left)/r.width*100)}
reveal.addEventListener('pointerdown',event=>{if(event.button!==0)return;revealDragging=true;reveal.setPointerCapture(event.pointerId);reveal.focus();event.preventDefault();revealAt(event)});
reveal.addEventListener('pointermove',event=>{if(revealDragging){event.preventDefault();revealAt(event)}});
reveal.addEventListener('pointerup',()=>{revealDragging=false});reveal.addEventListener('pointercancel',()=>{revealDragging=false});
